import os, json, re

brain_dir = '/Users/dev/.gemini/antigravity/brain'
results = []

def extract_req(text):
    m = re.search(r'<USER_REQUEST>\s*(.*?)\s*</USER_REQUEST>', text, re.DOTALL)
    if m:
        return m.group(1).strip()
    return text.strip()

for cid in os.listdir(brain_dir):
    p = os.path.join(brain_dir, cid, '.system_generated', 'logs', 'transcript.jsonl')
    if os.path.exists(p):
        mtime = os.path.getmtime(p)
        user_prompts = []
        with open(p, 'r', errors='ignore') as f:
            for line in f:
                try:
                    data = json.loads(line)
                    if data.get('type') == 'USER_INPUT':
                        c = data.get('content', '')
                        user_prompts.append(extract_req(c))
                except:
                    pass
        if user_prompts:
            results.append((mtime, cid, user_prompts))

results.sort(reverse=True)
for mtime, cid, prompts in results[:30]:
    print(f'CID: {cid}')
    for p in prompts[:2]:
        print('  ' + p.replace('\n', ' ')[:120])
