import os, glob, json

def search_files(dir_path):
    matches = []
    for root, dirs, files in os.walk(dir_path):
        for f in files:
            if f.endswith('.jsonl') or f.endswith('.json') or f.endswith('.md') or f.endswith('.txt'):
                p = os.path.join(root, f)
                # check size < 50MB
                try:
                    if os.path.getsize(p) > 50*1024*1024:
                        continue
                    with open(p, 'r', errors='ignore') as fp:
                        content = fp.read()
                        if 'trading bot' in content.lower() or 'tradingbot' in content.lower():
                            mtime = os.path.getmtime(p)
                            matches.append((mtime, p))
                except:
                    pass
    return matches

print('Searching ~/.gemini...')
gemini_matches = search_files('/Users/dev/.gemini')
gemini_matches.sort(reverse=True)
for mtime, p in gemini_matches[:20]:
    print(mtime, p)
